async function fetchEnc(){for(const u of FEEDS){try{const r=await fetch(u+'?t='+Date.now(),{cache:'no-store'});if(r.ok){const e=await r.json();ls.setItem('elEnc',JSON.stringify(e));return e}}catch(x){}}const c=ls.getItem('elEnc');if(c)return JSON.parse(c);throw 'offline'}
